function fibonacci(n):
    if n <= 1:
        return n

    return fibonacci(n - 1) + fibonacci(n - 2)

function crackLock(n, options):
    if n == 0:
        return [[]]

    smallerCombinations = crackLock(n - 1, options)
    allCombinations = []

    for each combination in smallerCombinations:
        for each option in options:
            newCombination = combination + [option]
            allCombinations.append(newCombination)

    return allCombinations
